import cv2, numpy as np
cap=cv2.VideoCapture('/app/example_video.mp4')
prev=None
rows=[]
i=0
while True:
    ok, frame=cap.read()
    if not ok: break
    small=cv2.resize(frame,(64,48))
    g=cv2.cvtColor(small,cv2.COLOR_BGR2GRAY).astype(np.float32)
    hsv=cv2.cvtColor(small,cv2.COLOR_BGR2HSV)
    h=cv2.calcHist([hsv],[0,1],None,[32,32],[0,180,0,256])
    cv2.normalize(h,h)
    if prev is not None:
        pg,ph=prev
        rows.append((i,float(np.mean(np.abs(g-pg))),float(cv2.compareHist(ph,h,cv2.HISTCMP_CORREL)),float(g.mean())))
    prev=(g,h)
    i+=1
cap.release()
print('frames 410-455')
for f,mad,corr,mean in rows:
    if 410<=f<=455:
        print(f'{f:3d} mad={mad:7.4f} corr={corr:7.4f} mean={mean:7.2f}')
print('candidate runs mad>0.05')
